-- 130: Original BrillaPrep WASSCE BrillaPrep transitional Applied Electricity beta content blueprint beta questions, part 1.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_130_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_130_guard;
INSERT INTO _migration_130_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_001' AND NOT (q.topic_id IS 'topic_was_elect_1' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What should be done first before working on a mains electrical circuit?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Isolate the supply and verify that the circuit is de-energised","B. Touch a conductor to test it by sensation","C. Replace the fuse while current is flowing","D. Assume an open switch guarantees isolation"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Safe isolation requires disconnection, prevention of unintended reconnection and verification with suitable test equipment before conductors are handled. Therefore the correct answer is A: Isolate the supply and verify that the circuit is de-energised.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_001' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_130_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_002' AND NOT (q.topic_id IS 'topic_was_elect_1' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A current meter reads 2.5 A. Which SI base unit is represented by the symbol A?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Volt","B. Ampere","C. Ohm","D. Watt"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Current is the rate of flow of electric charge and is measured in amperes, while voltage, resistance and power use different units. Therefore the correct answer is B: Ampere.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_002' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_130_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_003' AND NOT (q.topic_id IS 'topic_was_elect_1' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A 12 V device draws 2 A. What electrical power does it use?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 6 W","B. 10 W","C. 24 W","D. 48 W"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Electrical power in a direct-current resistive load is P = VI, so 12 multiplied by 2 gives 24 watts. Therefore the correct answer is C: 24 W.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_003' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_130_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_004' AND NOT (q.topic_id IS 'topic_was_elect_1' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does resistance describe?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The rate of using electrical energy only","B. The amount of charge stored in every source","C. The magnetic direction of a compass","D. Opposition to electric current flow"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Resistance relates voltage to current and is measured in ohms; material, length, cross-sectional area and temperature can affect it. Therefore the correct answer is D: Opposition to electric current flow.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_004' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_130_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_005' AND NOT (q.topic_id IS 'topic_was_elect_1' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why must a person avoid using water on energised electrical equipment?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Water can create conductive paths and increase shock or fault risk","B. Water always raises insulation resistance","C. It safely isolates every live conductor","D. It guarantees that protective devices cannot operate"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Ordinary water and contaminants may conduct current, exposing people and equipment to shock, short-circuit and arc hazards. Therefore the correct answer is A: Water can create conductive paths and increase shock or fault risk.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_005' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
